<template><view class="tab-page"><view class="nav-title">我的</view><view class="profile"><view class="avatar">{{ first }}</view><view><b>{{ session.user?.name || '张三' }}</b><text>代理人ID：AG10086</text></view></view><view class="menu"><view v-for="item in menu" :key="item" @tap="notice"><text>{{item}}</text><b>›</b></view></view><button class="logout" @tap="logout">退出登录</button><agent-tabbar active="profile" /></view></template>
<script setup>import{computed,onMounted}from'vue';import AgentTabbar from '../../components/agent-tabbar.vue';import{enforcePortal}from'../../core/route-guard';import{clearSession,session}from'../../core/session';onMounted(()=>enforcePortal('agent'));const first=computed(()=>((session.user?.name)||'张').slice(0,1));const menu=['账号与安全','帮助与反馈','关于我们'];function notice(){uni.showToast({title:'功能待接入',icon:'none'})}function logout(){clearSession();uni.reLaunch({url:'/pages/auth/login?portal=agent'})}</script>
<style lang="scss" scoped>.tab-page{min-height:100vh;padding:calc(42rpx + env(safe-area-inset-top)) 34rpx 150rpx;background:#f7f8fc;box-sizing:border-box;color:#27314a}.nav-title{font-size:37rpx;font-weight:750}.profile{display:flex;align-items:center;gap:20rpx;margin-top:40rpx;padding:31rpx;border-radius:25rpx;background:#fff}.avatar{display:flex;align-items:center;justify-content:center;width:88rpx;height:88rpx;border-radius:50%;background:#dfe3ff;color:#5865f2;font-size:34rpx;font-weight:750}.profile b,.profile text{display:block}.profile b{font-size:30rpx}.profile text{margin-top:9rpx;color:#9ba3b4;font-size:21rpx}.menu{overflow:hidden;margin-top:26rpx;border-radius:22rpx;background:#fff}.menu view{display:flex;justify-content:space-between;padding:29rpx;border-bottom:1rpx solid #f0f1f5;font-size:26rpx}.menu view:last-child{border:0}.menu b{color:#a2aabb;font-size:34rpx;line-height:.6}.logout{width:100%;margin-top:40rpx;border:1rpx solid #dce0eb;border-radius:16rpx;background:#fff;color:#5865f2;font-size:27rpx;line-height:86rpx}.logout::after{border:0}</style>
